from __future__ import annotations
from dataclasses import dataclass
from typing import Optional

@dataclass(frozen=True)
class Config:
    a: int
    b: int
    value: int

def step(c: Config, limit: int) -> Optional[Config]:
    if c.value >= limit:
        return None
    return Config(c.b, c.a + c.b, c.value + c.a)

def compare(limit: int = 50, budget: int = 20) -> bool:
    mutable = Config(1, 1, 0)
    encoded = (1, 1, 0)
    for _ in range(budget):
        successor = step(mutable, limit)
        a, b, value = encoded
        fixed = None if value >= limit else (b, a + b, value + a)
        if (None if successor is None else (successor.a, successor.b, successor.value)) != fixed:
            return False
        if successor is None:
            return True
        mutable, encoded = successor, fixed
    return True

if __name__ == "__main__":
    print("Exact traces:", compare())

from __future__ import annotations
from typing import Callable, Optional

def monitor(step: Callable[[int], Optional[int]], start: int, horizon: int) -> str:
    state = start
    for n in range(horizon + 1):
        nxt = step(state)
        if nxt is None:
            return f"halt observed at stage {n}"
        if n < horizon:
            state = nxt
    return f"survived {horizon} steps; no infinite claim made"

def delayed(delay: int) -> Callable[[int], Optional[int]]:
    return lambda n: None if n >= delay else n + 1

if __name__ == "__main__":
    for bound in (5, 10, 25):
        print(monitor(delayed(11), 0, bound))

from __future__ import annotations

def shared_prefix(horizon: int) -> tuple[list[int], list[int], int]:
    perpetual = list(range(horizon + 1))
    delayed = list(range(horizon + 1))
    halt_time = horizon + 1
    return perpetual, delayed, halt_time

if __name__ == "__main__":
    for horizon in (4, 12, 30):
        p, d, halt = shared_prefix(horizon)
        print(horizon, p == d, halt)

