def dovetail(left: Callable[[int, int], bool], right: Callable[[int, int], bool], item: int) -> tuple[str, int]:
    """Illustrate parallel recognition; assumes exactly one side eventually accepts."""
    stage = 0
    while True:
        if left(item, stage):
            return ("left", stage)
        if right(item, stage):
            return ("right", stage)
        stage += 1

